function UIActivityPtMainDialog:OnInitialize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        local argument = self.controller.Argument.parameters
        if not argument then return end

        self._curUuid = checkNumber(argument.activityUuid)
        local isFinish = false
        ActivityPtComponent:OverseaActivityPtQuestHomeReq(self._curUuid, function()
            isFinish = true
        end)
        while not isFinish do
            coroutine.yield()
        end

        local t = ActivityPtComponent:GetActivityConf()
        local goPath = ActivityPtUtils.GetActivityPtMainGoPath(t.prefab)
        self._nodeGo = GameUtils.LoadBundleAsync(goPath, self.controller.gameObject)
        if not isNull(self._nodeGo) then
            local vo = ActivityPtUtils.GetFirstPlotId(t.id)
            local isShowFirst = ActivityPtUtils.IsPassQuest(vo.id)
            local plotId = checkInt(CfUtils.GetLocalData("UIActivityPtPlot", 0))
            if plotId == 0 then
                CfUtils.WriteLocalData("UIActivityPtPlot", vo.id)
            end 
            if isShowFirst then
                self:RefreshNodeShow()
            else
                ActivityPtComponent:OverseaActivityPtQuestPlotReq(self._curUuid, vo.id, function(rewards)
                    self:PlayPlot(vo, function()
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards, cb = function()
                            self:RefreshNodeShow()
                            local t = ActivityPtComponent:GetActivityConf()
                            if isNotNull(t.bgm) then
                                ---@type CriWareUtils
                                local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
                                CriWareUtils.PlayMusicById(t.bgm)
                            end
                        end } })
                    end)
                end)
            end
        end

        local index = 0
        if not isNull(self.controller) and not isNull(self.controller.Argument) then
            index = self.controller.Argument.extra
        end
        if isNotNull(t.bgm) and checkNumber(index) == 0 then
            ---@type CriWareUtils
            local CriWareUtils = import('Game.Entry.CriWareUtilsFix')
            CriWareUtils.StopAll()
            CriWareUtils.PlayMusicById(t.bgm)
            self.controller:SetExtraArgument(1)
        end
    end))
    return coWait
end

function UIActivityPtMainDialog:RefreshNodeShow()
    local t = ActivityPtComponent:GetActivityConf()
    if t.openPage == 1 then
        local scr = CfUtils.GetLuaScr(self._nodeGo, "Game.UI.FightReady.UIActivityPt.ActivityPtMain.UIActivityPtMainOpenPageNode")
        if scr then
            scr:Refresh(self._curUuid)
        end
    else
        local scr = CfUtils.GetLuaScr(self._nodeGo, "Game.UI.FightReady.UIActivityPt.ActivityPtMain.UIActivityPtMainNode")
        if scr then
            scr:Refresh(self._curUuid)
        end
    end
end

---播放剧情
function UIActivityPtMainDialog:PlayPlot(vo, endCb)
    if not vo then
        return
    end
    if self._isPlayPlot then
        return
    end
    self._isPlayPlot = true
    local plotIds = CfUtils.Split(vo.storyId)
    if not plotIds then
        GameUtils.Toast(localize("该关卡没有剧情参数"))
        self._isPlayPlot = false
        return
    end
    
    self._curPlotIndex = 1
    self:PlayingPlot(plotIds, vo, endCb)
end

---剧情播放中
function UIActivityPtMainDialog:PlayingPlot(plotIds, vo, endCb)
    local co = cs_coroutine.start(function()
        ::start::
        local wait = true
        ChapterUtils.ProcessChapter(checkNumber(plotIds[self._curPlotIndex]), function(go)
            self._plotGo = go
        end, function()
            --所有的播完结束
            wait = false
        end)

        while wait do
            coroutine.yield()
        end

        KTool.SafeDelete(self._plotGo)

        --dispose
        coroutine.yield()
        
        if self._curPlotIndex >= table.count(plotIds) then
            -- GameUtils.PlayMainBGM()
            if endCb then
                endCb()
            end

            self._isPlayPlot = false
        else
            self._curPlotIndex = self._curPlotIndex + 1
            goto start
        end
    end)
end

function UIActivityPtMainDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIActivityPtMainDialog
